def scoring_from_quizzes(apps, schema_editor):
    """BAR-01 : chaque question reçoit le barème du plus ancien QCM qui la contient ; une
    question d'aucun QCM garde le barème vide (la base, b=1, m=0, v=0)."""
    Question = apps.get_model("bank", "Question")
    QuizItem = apps.get_model("bank", "QuizItem")
    for question in Question.objects.all():
        item = QuizItem.objects.filter(question=question).select_related("quiz").order_by("quiz_id").first()
        if item is None:
            continue
        quiz, multiple = item.quiz, question.kind == "multiple"
        kind = "multiple" if multiple else "simple"
        question.scoring = legacy_scoring(
            multiple=multiple,
            n_choices=question.choices.count(),
            b=getattr(quiz, f"{kind}_b"),
            m=getattr(quiz, f"{kind}_m"),
            v=getattr(quiz, f"{kind}_v"),
            p=quiz.multiple_p if multiple else None,
        )
        question.save(update_fields=["scoring"])


